        vm.assume(amount <= address(c).balance);

        Receiver r = new Receiver();

        uint256 prevBalance = address(c).balance;
        bool success;

        vm.prank(actor);
        try c.sendTo(address(r), amount) {
            success = true;
        } catch {
            success = false;
        }

        bool expectedSuccess = (actor == address(this));
        assertTrue(success == expectedSuccess);
    }
}

